class Calculator:
    def __init__(self):
        self.history = []

    def add(self, a, b):
        result = a + b
        self.history.append(f"{a} + {b} = {result}")
        return result

    def multiply(self, a, b):
        result = a * b
        self.history.append(f"{a} * {b} = {result}")
        return result

    def divide(self, a, b):
        if b == 0:
            return "Error: Division by zero"
        result = a / b
        self.history.append(f"{a} / {b} = {result}")
        return result

    def show_history(self):
        for entry in self.history:
            print(entry)

calc = Calculator()
calc.add(10, 5)
calc.multiply(4, 3)
calc.divide(20, 4)
calc.show_history()

class Task:
    def __init__(self, task_id, title):
        self.task_id = task_id
        self.title = title
        self.completed = False

    def mark_done(self):
        self.completed = True

    def get_status(self):
        status = "[V]" if self.completed else "[ ]"
        return f"{status} #{self.task_id}: {self.title}"

class TaskManager:
    def __init__(self):
        self.tasks = []

    def add_task(self, title):
        new_id = len(self.tasks) + 1
        task = Task(new_id, title)
        self.tasks.append(task)
        return task

    def complete_task(self, task_id):
        for task in self.tasks:
            if task.task_id == task_id:
                task.mark_done()
                return True
        return False

    def list_all(self):
        for task in self.tasks:
            print(task.get_status())

# Run Task Manager
manager = TaskManager()
manager.add_task("Learn Python in PyTeen")
manager.add_task("Build independent project")
manager.complete_task(1)
manager.list_all()

import numpy as np

def relu(x):
    return np.maximum(0, x)

def sigmoid(x):
    return 1 / (1 + np.exp(-x))

vals = np.array([-3.0, 0.0, 3.0])
relu_out = relu(vals)
sigmoid_out = sigmoid(vals)

print(f"Input: {vals.tolist()}")
print(f"ReLU: {relu_out.tolist()}")
print(f"Sigmoid: {[round(float(v), 2) for v in sigmoid_out]}")
